async function submitRegister(event){
  event.preventDefault();
  if(!localStorageReady())return authMessage('Browser storage is unavailable. Use Chrome/Edge with Live Server and allow site storage.');
  const name=$('registerName').value.trim(),email=$('registerEmail').value.trim().toLowerCase(),password=$('registerPassword').value,confirm=$('registerConfirm').value;
  if(name.length<2)return authMessage('Enter a valid full name.');
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return authMessage('Enter a valid email address.');
  if(password.length<6)return authMessage('Password must contain at least 6 characters.');
  if(password!==confirm)return authMessage('Passwords do not match.');
  const accounts=getLocalAccounts();
  if(accounts.some(a=>String(a.email||'').toLowerCase()===email))return authMessage('An account with this email already exists. Sign in instead.');
  const uuid=window.crypto?.randomUUID?window.crypto.randomUUID():('user-'+Date.now()+'-'+Math.random().toString(36).slice(2));
  const now=new Date().toISOString(),account={_id:'local-user-'+uuid,name,email,passwordHash:await hashPassword(password),role:'learner',createdAt:now,lastActive:now,xp:0,points:0,streak:0,badges:[],certificates:[],completedLessons:[],completedCourses:[],quizPassed:[],firewallCount:0,localOnly:true};
  accounts.push(account);
  if(!saveLocalAccounts(accounts))return;
  user={...account};delete user.passwordHash;user.localOnly=true;localSave();updateLoginNav();authMessage('Account created successfully. Welcome to Firewall Academy X!','good');toast('Learner account created successfully.');show('dashboard');renderDashboard();updateProfile();
}
async function submitLogin(event){
  event.preventDefault();
  if(!localStorageReady())return authMessage('Browser storage is unavailable. Use Chrome/Edge with Live Server and allow site storage.');
  const email=$('loginEmail').value.trim().toLowerCase(),password=$('loginPassword').value;
  if(!email||!password)return authMessage('Enter your email and password.');
  const accounts=getLocalAccounts(),account=accounts.find(a=>String(a.email||'').toLowerCase()===email);
  if(!account)return authMessage('No learner account was found for this email. Create an account first.');
  if(!account.passwordHash)return authMessage('This account needs to be recreated. Please use Create Account.');
  const hash=await hashPassword(password);
  if(account.passwordHash!==hash)return authMessage('Incorrect email or password.');
  account.lastActive=new Date().toISOString();saveLocalAccounts(accounts);user={...account};delete user.passwordHash;user.localOnly=true;localSave();updateLoginNav();authMessage('Signed in successfully.','good');toast(`Welcome back, ${user.name}.`);show('dashboard');renderDashboard();updateProfile();
}

