async function changeAdminPassword(event){
  event.preventDefault();
  const status=$('adminPasswordStatus');
  const current=$('adminCurrentPassword').value;
  const next=$('adminNewPassword').value;
  const confirm=$('adminConfirmPassword').value;
  if(!sessionStorage.getItem('faxAdminAuth')){if(status){status.textContent='Admin authentication is required.';status.className='authStatus bad';}return;}
  if(next.length<8){if(status){status.textContent='New password must contain at least 8 characters.';status.className='authStatus bad';}return;}
  if(next!==confirm){if(status){status.textContent='New passwords do not match.';status.className='authStatus bad';}return;}
  const expected=await getAdminPasswordHash(),actual=await hashPassword(current);
  if(actual!==expected){if(status){status.textContent='Current admin password is incorrect.';status.className='authStatus bad';}return;}
  const newHash=await hashPassword(next);
  localStorage.setItem('faxAdminPasswordHash',newHash);
  localStorage.setItem('faxAdminPasswordConfigured','1');
  $('adminPasswordForm').reset();
  if(status){status.textContent='Admin password updated successfully. Use the new password next time you log in.';status.className='authStatus good';}
  toast('Admin password changed successfully.','ok');
}
