async function api(url,opts={}){
  // Browser-only adapter: keeps existing feature code working without Node.js/MongoDB.
  serverOnline=true;
  const path=String(url||'').split('?')[0];
  const method=String(opts.method||'GET').toUpperCase();
  let body=null; try{body=opts.body?JSON.parse(opts.body):null}catch(_){body=null;}
  if(path==='/api/courses')return COURSE_DATA;
  if(path==='/api/paths')return PATH_DATA;
  if(path==='/api/resources')return RESOURCE_DATA;
  if(path==='/api/analyze-rule'){
    const rules=body?.rules||[]; const enabled=rules.filter(r=>r.enabled!==false);
    const allow=enabled.filter(r=>r.action==='ALLOW').length, deny=enabled.filter(r=>r.action==='DENY').length;
    const inbound=enabled.filter(r=>r.direction==='INBOUND').length, outbound=enabled.filter(r=>r.direction==='OUTBOUND').length;
    const checks=[]; let score=100;
    if(enabled.some(r=>r.source==='ANY'&&r.destination==='ANY'&&r.protocol==='ANY')){score-=35;checks.push('Broad ANY/ANY/ANY rule detected; narrow the scope or document the exception.');}
    if(!enabled.some(r=>r.action==='DENY')){score-=20;checks.push('No explicit deny rule is present; confirm the intended default policy.');}
    if(!enabled.some(r=>r.logging)){score-=10;checks.push('Consider logging important policy decisions for verification and troubleshooting.');}
    const dup=new Set(); let duplicates=0; rules.forEach(r=>{const k=firewallRuleKey(r);if(dup.has(k))duplicates++;dup.add(k)});
    if(duplicates){score-=10;checks.push(`${duplicates} duplicate rule(s) should be removed.`);}
    if(!checks.length)checks.push('Policy uses specific scope and has a deliberate deny/logging posture. Continue with controlled testing.');
    score=Math.max(0,Math.min(100,score));
    return {risk:score<50?'High':score<80?'Medium':'Low',score,summary:'Browser-local policy analysis completed. No firewall changes were executed.',totalRules:enabled.length,allowRules:allow,denyRules:deny,inboundRules:inbound,outboundRules:outbound,duplicatesRemoved:duplicates,checks};
  }
  if(path==='/api/generate-code')return {code:clientGenerate(body||{})};
  if(path.startsWith('/api/users/')&&path.endsWith('/xp')){const amount=Number(body?.amount||0);if(user){user.xp=(user.xp||0)+amount;user.points=(user.points||0)+amount;unlockThresholdBadges();user.lastActive=new Date().toISOString();localSave();return user;}return null;}
  return null;
}
