function courseSpecificLessonData(course,index){
  const cid=course._id||course.id; const rich=COURSE_RICH_CONTENT[cid]; const name=course.lessons[index];
  if(rich&&rich.modules[index]){
    const m=rich.modules[index]; const q=rich.finalAssessment[index%rich.finalAssessment.length];
    return {goal:m.summary,explain:m.content,example:m.example,scenario:rich.caseStudy.scenario,task:m.activity,objectives:rich.objectives.slice(0,5),keyPoints:rich.takeaways.slice(0,5),whyItMatters:rich.summary,takeaways:rich.takeaways.slice(0,5),commonMistakes:[`Applying ${name} without checking the ${rich.prerequisites[0]} prerequisite`,`Using a broader scope than the ${course.title} requirement needs`,`Skipping evidence or verification`,`Changing policy without documenting the reason`],q:q.question,opts:q.options,a:q.answer,why:q.explanation};
  }
  return genericLesson(name,index);
}
function lessonData(name,index){const active=window.__ACTIVE_LESSON_COURSE__; if(active){const idx=active.lessons.indexOf(name); if(idx>=0)return courseSpecificLessonData(active,idx);} return LESSON_LIBRARY[name]||genericLesson(name,index);}
async function completeLessonInteractive(courseId,index){const c=allCourses.find(x=>(x._id||x.id)===courseId)||COURSE_DATA.find(x=>(x._id||x.id)===courseId);if(!c)return;const key=(c._id||c.id)+'::'+index;if((user.completedLessons||[]).includes(key)){toast('Lesson already completed','warn');return;}user.completedLessons=user.completedLessons||[];user.completedLessons.push(key);if(!user.localOnly){const r=await api('/api/users/'+user._id+'/lesson',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lessonKey:key,completed:true})});if(r)user=r}else{user.xp=(user.xp||0)+5;user.points=(user.points||0)+5;unlockThresholdBadges();localSave();}updateProfile();renderDashboard();openCourse(courseId);toast('Lesson completed — +5 XP');}
async function startLesson(courseId,index=0){if(!requireLogin('Sign in before starting a lesson.'))return;const c=allCourses.find(x=>(x._id||x.id)===courseId)||COURSE_DATA.find(x=>(x._id||x.id)===courseId);if(!c){toast('Course could not be loaded','warn');return;}if(index<0||index>=c.lessons.length){toast('Lesson not found','warn');return;}show('courses');openInteractiveLesson(courseId,index)}

function lessonPracticeKey(courseId,index){return 'fwLessonPractice::'+courseId+'::'+index;}
function lessonPracticeState(courseId,index){const all=JSON.parse(localStorage.getItem('fwLessonPractice')||'{}');return all[lessonPracticeKey(courseId,index)]||null;}
function markLessonPractice(courseId,index){const source=$('practiceSource')?.value,action=$('practiceAction')?.value,logging=$('practiceLogging')?.value,notes=$('practiceNotes')?.value.trim();const out=$('practiceResult');const c=allCourses.find(x=>(x._id||x.id)===courseId)||COURSE_DATA.find(x=>(x._id||x.id)===courseId);const lesson=c?.lessons?.[index]||'';if(!source||!action||!logging){if(out)out.innerHTML='<div class="quizFeedback wrong">Choose a source scope, decision, and logging option first.</div>';return false;}if(source==='any'){if(out)out.innerHTML='<div class="quizFeedback wrong">For this practice, avoid ANY / unrestricted. Use a specific host, trusted subnet, or known service.</div>';return false;}if(logging!=='on'){if(out)out.innerHTML='<div class="quizFeedback wrong">Enable logging so you can verify the decision with evidence.</div>';return false;}if(notes.length<20){if(out)out.innerHTML='<div class="quizFeedback wrong">Add a short verification note (at least 20 characters) explaining what you would verify next.</div>';const box=$('practiceNotes');if(box)box.focus();return false;}const all=JSON.parse(localStorage.getItem('fwLessonPractice')||'{}');all[lessonPracticeKey(courseId,index)]={source,action,logging,notes,completed:true,at:new Date().toISOString(),lesson};localStorage.setItem('fwLessonPractice',JSON.stringify(all));if(out)out.innerHTML='<div class="quizFeedback correct">✓ Practice validated. Specific scope + explicit decision + enabled logging is ready to test. • +10 XP</div>';const status=$('practiceStatus');if(status)status.textContent='✓ Practice completed';const btn=$('finishLessonBtn');if(btn){const q=!!(user?.quizPassed||[]).includes((allCourses.find(x=>(x._id||x.id)===courseId)||COURSE_DATA.find(x=>(x._id||x.id)===courseId))._id+'::quiz::'+index);btn.disabled=!q;btn.textContent=q?'✓ Mark Lesson Complete':'🔒 Pass the quiz first';}if(user){const awardKey=lessonPracticeKey(courseId,index)+'::xp';const xp=JSON.parse(localStorage.getItem('fwLessonPracticeXP')||'{}');if(!xp[awardKey]){xp[awardKey]=true;localStorage.setItem('fwLessonPracticeXP',JSON.stringify(xp));if(user.localOnly){user.xp=(user.xp||0)+10;user.points=(user.points||0)+10;unlockThresholdBadges();localSave();}else{gain(10,'lesson practice');}}}return true;}
function saveLessonNotes(key){const box=$('practiceNotes');if(!box)return;const all=JSON.parse(localStorage.getItem('fwLessonNotes')||'{}');all[key]=box.value.trim();localStorage.setItem('fwLessonNotes',JSON.stringify(all));const status=$('practiceStatus');if(status)status.textContent='✓ Practice notes saved in this browser';toast('Practice notes saved');}
