function editRule(index){const r=builderRules[index];if(!r)return;builderEditIndex=index;$('ruleEditorHeading').textContent='Edit firewall rule';$('ruleEditMode').textContent=`Editing Rule ${index+1}`;$('addRule').textContent='✓ Update Rule';$('cancelEdit').hidden=false;$('ruleName').value=r.name||'';$('ruleAction').value=r.action;$('ruleDirection').value=r.direction;$('ruleProtocol').value=r.protocol;$('ruleSource').value=r.source;$('ruleDestination').value=r.destination;$('ruleSourcePort').value=r.sourcePort;$('ruleDestinationPort').value=r.destinationPort;$('ruleEnabled').checked=r.enabled!==false;$('ruleLogging').checked=!!r.logging;document.getElementById('ruleEditorHeading')?.scrollIntoView({behavior:'smooth',block:'center'});}
