function clientGenerate({platform,language,rules,config}){
  const rs=rules||normalizedFirewall(config).rules;
  if(language==='PowerShell'||platform.includes('Windows'))return ['# Firewall Academy X - Windows Defender Firewall',...rs.filter(r=>r.enabled).map((r,i)=>{const dir=r.direction==='OUTBOUND'?'Outbound':'Inbound',action=r.action==='ALLOW'?'Allow':'Block',parts=[`New-NetFirewallRule -DisplayName "FA-X Rule ${i+1}" -Direction ${dir} -Action ${action}`];if(r.protocol!=='ANY')parts.push(`-Protocol ${r.protocol}`);const local=r.direction==='INBOUND'?r.destination: r.source, remote=r.direction==='INBOUND'?r.source:r.destination, lp=r.direction==='INBOUND'?r.destinationPort:r.sourcePort, rp=r.direction==='INBOUND'?r.sourcePort:r.destinationPort;if(local!=='ANY')parts.push(`-LocalAddress "${local}"`);if(remote!=='ANY')parts.push(`-RemoteAddress "${remote}"`);if(lp!=='ANY'&&r.protocol!=='ICMP')parts.push(`-LocalPort "${lp}"`);if(rp!=='ANY'&&r.protocol!=='ICMP')parts.push(`-RemotePort "${rp}"`);return parts.join(' ')})].join('\n');
  if(platform.includes('iptables')||language==='Shell')return ['# Firewall Academy X - Generated Policy',...rs.filter(r=>r.enabled).flatMap((r,i)=>{const chain=r.direction==='OUTBOUND'?'OUTPUT':'INPUT',a=r.action==='ALLOW'?'ACCEPT':'DROP',p=['iptables','-A',chain];if(r.protocol!=='ANY')p.push('-p',r.protocol.toLowerCase());if(r.source!=='ANY')p.push('-s',r.source);if(r.destination!=='ANY')p.push('-d',r.destination);if(r.sourcePort!=='ANY'&&['TCP','UDP'].includes(r.protocol))p.push('--sport',r.sourcePort);if(r.destinationPort!=='ANY'&&['TCP','UDP'].includes(r.protocol))p.push('--dport',r.destinationPort);p.push('-j',a);return [`# Rule ${i+1}`,`# ${ruleToText(r)}`,p.join(' ')]})].join('\n');
  if(platform.includes('nftables'))return ['#!/usr/sbin/nft -f','# Firewall Academy X - Generated Policy','table inet filter {','  chain input {','    type filter hook input priority 0;','    policy accept;',...rs.filter(r=>r.enabled&&r.direction==='INBOUND').map(r=>'    '+nftRule(r)), '  }','  chain output {','    type filter hook output priority 0;','    policy accept;',...rs.filter(r=>r.enabled&&r.direction==='OUTBOUND').map(r=>'    '+nftRule(r)),'  }','}'].join('\n');
  if(platform.includes('firewalld'))return ['# Firewall Academy X - firewalld policy','# Inbound rules use the active zone/rich-rule model.',...rs.filter(r=>r.enabled).map(r=>firewalldRule(r))].join('\n');
  if(platform.includes('macOS')&&platform.includes('pf'))return ['# Firewall Academy X - macOS Packet Filter (pf)','anchor "firewall_academy_x";',...rs.filter(r=>r.enabled).map(r=>pfRule(r))].join('\n');
  if(platform.includes('macOS'))return ['# Firewall Academy X - macOS Application Firewall','## Application Firewall is application-oriented; port/IP policy is represented below for review only.',...rs.filter(r=>r.enabled).map((r,i)=>`# Rule ${i+1}: ${ruleToText(r)}`)].join('\n');
  return ['# Firewall Academy X educational policy',...rs.filter(r=>r.enabled).map(ruleToText)].join('\n');
}
function nftRule(r){const parts=[];if(r.source!=='ANY')parts.push('ip saddr '+r.source);if(r.destination!=='ANY')parts.push('ip daddr '+r.destination);if(r.protocol!=='ANY')parts.push(r.protocol.toLowerCase());if(r.sourcePort!=='ANY'&&['TCP','UDP'].includes(r.protocol))parts.push('sport '+r.sourcePort);if(r.destinationPort!=='ANY'&&['TCP','UDP'].includes(r.protocol))parts.push('dport '+r.destinationPort);parts.push(r.action==='ALLOW'?'accept':'drop');return parts.join(' ');}
function firewalldRule(r){if(r.direction==='OUTBOUND')return `# OUTBOUND ${ruleToText(r)} — use nftables for outbound enforcement with firewalld-managed systems`;const attrs=[];if(r.source!=='ANY')attrs.push(`source address="${r.source}"`);if(r.protocol!=='ANY'&&r.destinationPort!=='ANY')attrs.push(`port port="${r.destinationPort}" protocol="${r.protocol.toLowerCase()}"`);return `firewall-cmd --permanent --zone=public --add-rich-rule='rule ${attrs.join(' ')} ${r.action==='ALLOW'?'accept':'drop'}'`;}
function pfRule(r){const parts=[r.action==='ALLOW'?'pass':'block',r.direction==='OUTBOUND'?'out':'in'];if(r.protocol!=='ANY')parts.push('proto',r.protocol.toLowerCase());if(r.source!=='ANY')parts.push('from',r.source);if(r.destination!=='ANY')parts.push('to',r.destination);if(r.destinationPort!=='ANY'&&['TCP','UDP'].includes(r.protocol))parts.push('port',r.destinationPort);return parts.join(' ')+' flags S/SA';}
async function saveFirewall(){if(!requireLogin('Sign in before saving a firewall system.'))return;const n=currentBuilderNormalized();$('fwCode').value=n.text;renderRuleList();if(!n.rules.length)return toast('Add some valid rules first','warn');const payload={userId:user._id,name:$('fwName').value||'My Firewall',platform:$('platform').value,language:$('language').value,config:n.text,rules:n.rules};const r=!user.localOnly?await api('/api/firewalls',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}):null;if(!user.localFirewalls)user.localFirewalls=[];if(!r)user.localFirewalls.unshift({...payload,_id:'local-fw-'+Date.now(),createdAt:new Date().toISOString()});if(!r)user.firewallCount=(user.firewallCount||0)+1;await gain(25,'Saved firewall system');loadFirewalls();updateBuilderStats({duplicatesRemoved:n.duplicatesRemoved,status:'Saved'});toast(`Firewall saved • ${n.rules.length} unique rule${n.rules.length===1?'':'s'}`)}
async function loadFirewalls(){
  if(!user)return;
  const a=!user.localOnly?await api('/api/firewalls/'+user._id):null;
  const list=(a||user.localFirewalls||[]).map(x=>{const n=normalizedFirewall(x.config);return {...x,config:n.text,rules:n.rules,duplicatesRemoved:n.duplicatesRemoved};});
  $('firewalls').innerHTML=list.length?list.map(x=>`<div class="fw"><span><b>🛡️ ${esc(x.name)}</b><br><small>${esc(x.platform)} • ${esc(x.language)}</small><br><small>${new Date(x.createdAt||Date.now()).toLocaleString()}</small><br><small class="good">${x.rules?.length||0} normalized rules • ${x.duplicatesRemoved||0} duplicates removed</small></span><code>${esc(String(x.config).slice(0,900))}</code><button class="secondary" onclick='loadSavedFirewall(${JSON.stringify(x)})'>Load System</button></div>`).join(''):'<div class="empty card">No saved systems yet. Build your first one above.</div>';
}
function loadSavedFirewall(x){const n=normalizeRuleObjects(x.rules||parseFirewallRules(x.config||''));$('fwName').value=x.name||'My Firewall';$('platform').value=x.platform||'Linux / iptables';$('language').value=x.language||'Text Policy';setBuilderRules(n.rules,'Loaded');updateBuilderStats({duplicatesRemoved:n.duplicatesRemoved,status:'Loaded'});toast(`Loaded ${n.rules.length} normalized rules`);show('builder');}
function unlockThresholdBadges(){const xp=user.xp||0;const b=[['First 100 XP',100],['Rule Apprentice',250],['Firewall Defender',500],['Security Architect',750],['Quiz Champion',1000]];b.forEach(([n,t])=>{if(xp>=t&&!user.badges.includes(n))user.badges.push(n)});user.badges=[...new Set(user.badges)]}
