function renderCerts(){$('certBox').innerHTML=user?.certificates?.length?user.certificates.map((x,i)=>{const c=typeof x==='string'?{title:x,number:String(i+1).padStart(4,'0'),issuedAt:new Date().toISOString()}:x;const courseTitle=(c.title||'').replace(/ Certificate$/,'');return `<article class="certificateCard"><div class="certificateMini"><div class="certRibbon">FIREWALL ACADEMY X</div><div class="certSeal">🛡️</div><small>CERTIFICATE OF COMPLETION</small><h3>${esc(courseTitle)}</h3><p>Awarded to <b>${esc((user.name||'Learner').trim().replace(/\b\w/g,m=>m.toUpperCase()))}</b></p><div class="certMeta"><span>ID ${esc(c.number||String(i+1).padStart(4,'0'))}</span><span>${new Date(c.issuedAt||Date.now()).toLocaleDateString('en-GB')}</span></div></div><div class="certActions"><button class="primary" onclick='openCert(${JSON.stringify(c)})'>View Certificate</button><button class="secondary" onclick='downloadCertificate(${JSON.stringify(c)})'>⬇ Download Certificate</button><button class="secondary" onclick='printCertData(${JSON.stringify(c)})'>🖨 Save as PDF</button></div></article>`}).join(''):'<div class="card empty"><h3>📜 No certificates yet</h3><p class="muted">Complete a course to earn your first interactive certificate.</p><button class="primary" onclick="show(\'courses\')">Browse Courses</button></div>'}
function openModal(id){const m=$(id);m.classList.add('open');m.setAttribute('aria-hidden','false');document.body.classList.add('modalOpen')}
