function createCertificateId(){const year=new Date().getFullYear();let id='';const used=new Set();try{const accounts=getLocalAccounts();accounts.forEach(a=>(a.certificates||[]).forEach(c=>used.add(c.number)))}catch(_){}do{id='FAX-'+year+'-'+Math.random().toString(36).slice(2,8).toUpperCase()}while(used.has(id));return id}

