async function shareCertificate(c){const title=(c.title||'Firewall Academy X Certificate');const text=`I completed ${title} on Firewall Academy X.`;if(navigator.share){try{await navigator.share({title,text});return}catch{}}try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(text);else{const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();}toast('Certificate message copied to clipboard')}catch(_){toast('Sharing is unavailable in this browser.','warn')}}
async function verifyCertificate(c){const cert=(user?.certificates||[]).find(x=>x.number===(c.number||''));if(cert)toast(`✓ Verified: ${cert.number} • ${user.name} • ${new Date(cert.issuedAt).toLocaleDateString()}`);else toast('Certificate verification record was not found in this browser.','warn')}
async function gain(amount,reason){if(!user)return;const r=!user.localOnly?await api('/api/users/'+user._id+'/xp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount,reason})}):null;if(r)user=r;else{user.xp=(user.xp||0)+Number(amount);user.points=(user.points||0)+Number(amount);unlockThresholdBadges();if(/lab/i.test(reason)&&!user.badges.includes('Lab Explorer'))user.badges.push('Lab Explorer');if(/saved/i.test(reason)&&!user.badges.includes('Policy Builder'))user.badges.push('Policy Builder');if(/generated/i.test(reason)&&!user.badges.includes('Code Generator'))user.badges.push('Code Generator');if(/resource/i.test(reason)&&!user.badges.includes('Resource Navigator'))user.badges.push('Resource Navigator');user.lastActive=new Date().toISOString();localSave()}updateProfile();renderDashboard()}
function labAward(key,amount,reason){if(!user)return false;const storageKey='faxLabState::'+user._id;const state=JSON.parse(localStorage.getItem(storageKey)||'{}');if(state[key])return false;state[key]=true;localStorage.setItem(storageKey,JSON.stringify(state));gain(amount,reason);return true;}
function checkPort(){const v=$('portQ').value;if(!v)return $('portResult').innerHTML='<p class="warn">Choose a port before submitting.</p>';if(v==='443'){$('portResult').innerHTML='<p class="good">✓ Correct! TCP 443 is commonly used for HTTPS. For a public web server it is normally the intended web-service port; SSH and RDP should usually be restricted. +15 XP</p>';labAward('port',15,'Port Detective Lab')}else{$('portResult').innerHTML='<p class="warn">Not quite. Port '+esc(v)+' is a different service. This challenge asks for the common HTTPS service port: TCP 443.</p>'}}
function checkOrder(){const v=$('orderQ').value;if(!v)return $('orderResult').innerHTML='<p class="warn">Choose an answer before submitting.</p>';if(v==='block'){$('orderResult').innerHTML='<p class="good">✓ Correct! In a first-match style policy, the specific BLOCK must be evaluated before a broad ALLOW for the exception to work. +15 XP</p>';labAward('order',15,'Rule Order Lab')}else{$('orderResult').innerHTML='<p class="warn">Think about the narrow exception. If a broad ALLOW matches first, the later specific BLOCK may never be reached.</p>'}}
function checkLeast(){const v=$('leastInput').value.toUpperCase();if(!v.trim())return $('leastResult').innerHTML='<p class="warn">Write a rule first.</p>';const good=v.includes('443')&&!v.includes('ANY ANY');$('leastResult').innerHTML=good?'<p class="good">✓ Looks narrower: source, protocol and service are constrained. +20 XP</p>':'<p class="warn">Try a specific source, protocol and service instead of broad ANY values. Example: ALLOW TCP 443 FROM 10.0.0.0/24</p>';if(good)labAward('least',20,'Least Privilege Lab')}
