let aiHistory=[];
let aiBusy=false;
function markdownToHtml(text){
  let src=esc(String(text??'')).replace(/\r\n?/g,'\n');
  const blocks=[];
  src=src.replace(/```([\w+-]*)\n?([\s\S]*?)```/g,(_,lang,code)=>{
    const id=blocks.length;blocks.push(`<pre class="aiCode"><code>${code.trimEnd()}</code></pre>`);return `@@AICODE${id}@@`;
  });
  src=src.replace(/^###\s+(.+)$/gm,'<h4>$1</h4>')
    .replace(/^##\s+(.+)$/gm,'<h3>$1</h3>')
    .replace(/^#\s+(.+)$/gm,'<h3>$1</h3>')
    .replace(/^\s*[-*]\s+(.+)$/gm,'<li>$1</li>')
    .replace(/^\s*\d+\.\s+(.+)$/gm,'<li>$1</li>')
    .replace(/`([^`\n]+)`/g,'<code class="aiInlineCode">$1</code>')
    .replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')
    .replace(/\*([^*\n]+)\*/g,'<em>$1</em>');
  src=src.replace(/(?:<li>.*<\/li>\n?)+/g,m=>`<ul>${m}</ul>`);
  src=src.split(/\n{2,}/).map(part=>{
    if(/^<h[34]>/.test(part)||/^<ul>/.test(part)||/^@@AICODE\d+@@$/.test(part))return part;
    return part.replace(/\n/g,'<br>');
  }).join('');
  src=src.replace(/@@AICODE(\d+)@@/g,(_,i)=>blocks[Number(i)]||'');
  return src;
}
function renderAIMessage(text,type,meta=''){
  const c=$('chat');if(!c)return;
  const d=document.createElement('div');d.className=`chatMessage ${type}`;
  if(type==='user'){
    const body=document.createElement('div');body.className='messageBody';body.textContent=String(text??'');d.appendChild(body);
  }else{
    const avatar=document.createElement('span');avatar.className='msgAvatar';avatar.textContent='✦';
    const body=document.createElement('div');body.className='messageBody';
    const label=document.createElement('b');label.textContent=meta||'Firewall AI Coach';
    const p=document.createElement('div');p.className='aiMarkdown';p.innerHTML=markdownToHtml(text);
    body.append(label,p);d.append(avatar,body);
  }
  c.appendChild(d);c.scrollTop=c.scrollHeight;
}
function addChat(t,type){renderAIMessage(t,type)}
function setAIStatus(kind,label,detail){
  const status=$('aiStatusText'),provider=$('aiProviderStatus'),dot=status?.parentElement;
  if(status)status.textContent=label;
  if(dot){dot.classList.remove('offline','error','online');dot.classList.add(kind==='online'?'online':kind==='error'?'error':'offline')}
  if(provider)provider.textContent=detail;
}
