// Smart browser-only fallback. It does not pretend to be a remote LLM: it builds
// a useful answer from the user's intent, known security concepts and recent chat.
function localCoachText(q, history=[]){
  const raw=String(q||'').trim();
  const u=raw.toLowerCase().replace(/[^a-z0-9+#./ -]/g,' ');
  if(!raw)return'Ask me anything about networking, firewalls, cybersecurity, web security, ports, protocols, or your Firewall Academy coursework.';

  const recent=Array.isArray(history)?history.slice(-8).map(x=>String(x.text||'')).join(' ').toLowerCase():'';
  const topic=u.match(/stateful firewall|stateless firewall|packet filtering|firewall|nat|waf|ids|ips|owasp|tcp|udp|http|https|dns|ssh|rdp|smtp|ftp|tls|ssl|vpn|proxy|subnet|ip address|mac address|routing|switch|router|vlan|zero trust|least privilege|segmentation|logging|siem|phishing|malware|ransomware|ddos|authentication|authorization|encryption|hashing|sql injection|xss|csrf|api|rest api|database|mongodb|node js|javascript|html|css|python|java|operating system|linux|windows|cloud|network security|cybersecurity/i)||[];
  const topicName=topic[0] || (recent.match(/stateful firewall|stateless firewall|packet filtering|nat|waf|owasp|tcp|udp|dns|ssh|rdp|https|firewall|logging|vpn|vlan|zero trust|least privilege/i)||[])[0] || 'that topic';

  if(/^(hi|hello|hey|hii|hlo|yo|sup|good morning|good afternoon|good evening)[!. ]*$/i.test(raw))
    return'Hi! 👋 I’m Firewall AI Coach. Ask me a question in your own words—technical, conceptual, practical, or exam-related—and I’ll explain it step by step.';
  if(/^(thanks|thank you|thx|ty|great|okay|ok)[!. ]*$/i.test(raw))
    return'You’re welcome! 🔐 What would you like to explore next? You can ask for an explanation, example, comparison, troubleshooting help, a rule review, or an exam-style answer.';
  if(/who are you|what can you do|help me|what do you know/i.test(u))
    return'I’m Firewall AI Coach. I can explain networking and security concepts, walk through firewall rules, compare technologies, troubleshoot learning examples, explain ports and protocols, review defensive configurations, and help you prepare for exams.';

  // Contextual follow-ups.
  if(/^(why|how|what about|and|then|give me|show me|explain it|explain that|more|continue|another|example)/i.test(raw) && recent){
    if(/stateful/.test(recent)) return'For the stateful-firewall example: a client starts an HTTPS session to a server on TCP 443. The firewall records the connection state, so expected return traffic can be recognized as part of that established session. A stateless filter would evaluate each packet against its rule fields independently.';
    if(/nat/.test(recent)) return'For NAT, imagine a laptop at 192.168.1.20 accessing a website. Source NAT can translate the private source address to the network’s public address for the outbound connection. The firewall policy still decides whether the traffic is allowed.';
    if(/waf/.test(recent)) return'For a WAF, imagine a login request reaching /login. The WAF can inspect the HTTP request and apply application-layer rules before the request reaches the web application. It can allow, log, challenge, or block according to policy.';
    if(/owasp/.test(recent)) return'For OWASP, take broken access control as an example: a user should not be able to access another user’s record merely by changing an ID in a URL. The defensive control is server-side authorization on every protected resource.';
    if(/tcp|udp/.test(recent)) return'TCP provides reliable, ordered delivery and connection state; UDP has lower overhead and does not provide TCP-style reliability. The right choice depends on the application and its performance/reliability requirements.';
  }

  const facts={
    'stateful firewall':'A stateful firewall tracks active connection state. When an outbound HTTPS session is allowed, expected return traffic can be recognized as part of that established session. This reduces the need to write separate rules for every expected return packet.',
    'stateless firewall':'A stateless firewall evaluates packets independently using fields such as source, destination, protocol and port. It is simple and predictable, but it does not maintain the same connection-state context as a stateful firewall.',
    'firewall':'A firewall is a security control that enforces traffic policy between networks, hosts or applications. A useful rule normally defines source, destination, protocol, service/port, direction and action, with logging where evidence is useful.',
    'nat':'NAT translates network addresses. Source NAT is commonly used for outbound private-to-public traffic, while destination NAT or port forwarding can publish a service. NAT and firewall policy solve different problems and should not be treated as interchangeable.',
    'waf':'A Web Application Firewall protects HTTP/HTTPS applications at the application layer. It can inspect paths, parameters, headers and request patterns and then allow, log or block traffic according to policy.',
    'packet filtering':'Packet filtering compares packet attributes such as source, destination, protocol and port with configured rules. It is useful for access control, while stateful and application-layer controls add more context.',
    'owasp':'OWASP provides widely used application-security guidance and awareness material. For study, focus on risks such as broken access control, injection, security misconfiguration and identification/authentication failures, then learn the defensive controls for each.',
    'tcp':'TCP is connection-oriented and provides reliable, ordered delivery. It is commonly used by services such as HTTPS and SSH. A firewall can use TCP plus the required service port and trusted source/destination scope.',
    'udp':'UDP is connectionless and has lower protocol overhead than TCP. DNS commonly uses UDP 53, although some DNS traffic uses TCP. Firewall policy should match the actual service requirements.',
    'http':'HTTP is an application-layer protocol used for web communication. Plain HTTP does not provide transport encryption, so modern applications normally prefer HTTPS.',
    'https':'HTTPS is HTTP protected with TLS. Web traffic commonly uses TCP 443, although the exact transport can vary with newer protocols. A firewall rule should be as narrow as the application requires.',
    'dns':'DNS translates names such as example.com into network addresses and other records. Traditional DNS commonly uses UDP 53 and may use TCP 53 for certain operations or larger responses.',
    'ssh':'SSH provides secure remote administration and commonly uses TCP 22. Restrict administrative access to trusted sources, use strong authentication and log important access decisions.',
    'rdp':'RDP is a remote-desktop protocol commonly associated with TCP 3389. Avoid broad internet exposure; restrict access to trusted management paths and monitor authentication and connection logs.',
    'ids':'An IDS monitors activity and raises alerts about suspicious behavior. It is primarily a detection control rather than an enforcement point.',
    'ips':'An IPS is an inline security control that can detect and block suspicious traffic according to its rules and signatures. Because it can affect traffic, tuning and validation are important.',
    'vpn':'A VPN creates an authenticated/encrypted tunnel between endpoints or networks. It protects traffic in transit but does not automatically make every resource inside the tunnel trustworthy.',
    'vlan':'A VLAN logically separates Layer-2 network segments. Firewalls or Layer-3 controls can enforce policy between segments so systems do not receive unrestricted east-west access.',
    'zero trust':'Zero Trust is an approach that avoids automatically trusting a user or device merely because it is on an internal network. Access is continuously evaluated using identity, device, context and least-privilege policy.',
    'least privilege':'Least privilege means granting only the access required for a task. In firewall design, prefer specific sources, destinations, protocols and service ports over broad ANY/ANY rules.',
    'segmentation':'Network segmentation separates systems into zones with explicit controls between them. The goal is to reduce unnecessary communication and limit the blast radius of a compromise.',
    'logging':'Useful firewall logs usually include time, source, destination, protocol, service/port, action and rule identifier. Logs should support investigation without collecting unnecessary sensitive information.',
    'authentication':'Authentication answers “who are you?” using credentials, certificates, tokens or other factors. Multi-factor authentication adds another independent factor and can reduce account-compromise risk.',
    'authorization':'Authorization answers “what is this identity allowed to do?” It should be enforced server-side for protected resources and should follow least privilege.',
    'encryption':'Encryption transforms readable data into protected ciphertext using a cryptographic algorithm and key. It protects confidentiality when the key management and protocol are implemented correctly.',
    'hashing':'Hashing produces a fixed-length digest from input data. Secure password storage should use a password-hashing algorithm designed for passwords rather than a fast general-purpose hash.',
    'phishing':'Phishing uses deceptive messages or pages to trick people into revealing information or taking unsafe actions. Defenses include user awareness, strong authentication, URL verification, filtering and reporting processes.',
    'malware':'Malware is software designed to perform unwanted or harmful actions. Defensive controls include patching, least privilege, endpoint protection, backups and monitoring.',
    'ransomware':'Ransomware can encrypt or otherwise disrupt access to data. Strong backups, segmentation, patching, least privilege, endpoint controls and incident-response preparation reduce impact.',
    'ddos':'A DDoS attack attempts to overwhelm a service with traffic or requests. Defenses can include rate limiting, upstream filtering, CDN/DDoS protection and resilient architecture.',
    'sql injection':'SQL injection occurs when untrusted input changes the meaning of a database query. Parameterized queries and server-side validation are primary defenses.',
    'xss':'Cross-site scripting occurs when untrusted content is interpreted as executable script in a user’s browser. Context-aware output encoding, input handling and appropriate browser security controls reduce risk.',
    'csrf':'CSRF tricks a browser into sending an unwanted authenticated request. Defenses commonly include CSRF tokens, SameSite cookie settings and appropriate origin checks.',
    'api':'An API is an interface through which software components exchange data or actions. Secure APIs need authentication, authorization, input validation, rate limiting, logging and careful error handling.',
    'rest api':'A REST API commonly exposes resources through HTTP methods such as GET, POST, PUT/PATCH and DELETE. Good API design also uses clear status codes, validation and authorization.',
    'mongodb':'MongoDB is a document-oriented database. Applications commonly store JSON-like documents in collections and access them through a driver or framework.',
    'node js':'Node.js is a JavaScript runtime commonly used to build servers and command-line tools. Express is a popular framework for HTTP APIs running on Node.js.',
    'javascript':'JavaScript is a programming language widely used in browsers and also on servers through runtimes such as Node.js.',
    'html':'HTML defines the structure and semantic content of a web page. CSS controls presentation and JavaScript adds behavior and interactivity.',
    'css':'CSS controls the presentation of HTML, including layout, typography, spacing, responsive behavior and visual states.',
    'python':'Python is a general-purpose programming language often used for automation, data analysis, web services, scripting and security tooling.',
    'java':'Java is a general-purpose, object-oriented language and platform widely used for backend services, enterprise applications and Android development.',
    'linux':'Linux is an open-source family of operating-system kernels and distributions. It is widely used for servers, networking and security environments.',
    'windows':'Windows is a family of Microsoft operating systems. In a security context, useful topics include identity, permissions, event logs, Defender and firewall policy.',
    'cloud':'Cloud computing provides infrastructure and services on demand. Security still requires identity controls, network segmentation, logging, encryption, configuration management and least privilege.'
  };

  if(/study|exam|prepare|revision|midterm|semester|gtu|question paper/.test(u))
    return'For exam preparation, use this order: 1) learn the concept in simple words, 2) write one practical example, 3) practice a short problem, 4) review common mistakes, and 5) test yourself without notes. For Firewall Academy topics, prioritize firewall types, stateful inspection, ports/protocols, NAT, WAF/OWASP, rule design, logging and policy analysis.';

  // Normalize common phrases to a known concept.
  let key=topicName.toLowerCase();
  if(/tcp.*udp|udp.*tcp/.test(u)) key='tcp';
  if(/http.*https|https.*http/.test(u)) key='https';
  if(/sql injection/.test(u)) key='sql injection';
  if(/cross[- ]site scripting|\bxss\b/.test(u)) key='xss';
  if(/cross[- ]site request forgery|\bcsrf\b/.test(u)) key='csrf';
  if(/zero[- ]trust/.test(u)) key='zero trust';
  if(/least privilege/.test(u)) key='least privilege';
  if(/rest api/.test(u)) key='rest api';
  if(facts[key]){
    const base=facts[key];
    if(/why|benefit|advantage|important|purpose/.test(u)) return `${base}\n\nWhy it matters: it helps enforce a clear security boundary and makes the expected behavior easier to monitor and troubleshoot.`;
    if(/how|work|works|process|steps/.test(u)) return `${base}\n\nHow to approach it:\n1. Define the expected behavior.\n2. Identify the required source, destination, protocol and service.\n3. Apply the narrowest appropriate policy.\n4. Test the expected traffic.\n5. Review logs and adjust only when evidence shows a need.`;
    if(/example|example please|give me/.test(u)) return `${base}\n\nExample: start with a small, authorized test case, define the expected source and destination, apply the specific control, then verify both the result and the relevant logs.`;
    if(/difference|compare|vs|versus/.test(u)) return `${base}\n\nFor a comparison, focus on: where the control operates, what information it can inspect, whether it keeps state, what it can enforce, and what evidence it produces in logs.`;
    return base;
  }

  // Service-port questions.
  const ports={22:'SSH',53:'DNS',80:'HTTP',443:'HTTPS',25:'SMTP',110:'POP3',143:'IMAP',3389:'RDP'};
  const pm=u.match(/\b(?:port\s*)?(22|53|80|443|25|110|143|3389)\b/);
  if(pm){const svc=ports[pm[1]];return `Port ${pm[1]} is commonly associated with ${svc}. The number alone does not prove which service is actually running. For a firewall rule, verify the real service, protocol, source and destination, then allow only the traffic required and log important decisions.`;}

  // Rule-review requests.
  if(/review|check|audit|analy[sz]e/.test(u)&&/rule|policy|firewall|config/.test(u))
    return'For a defensive firewall-rule review, check: (1) source scope, (2) destination scope, (3) protocol, (4) service port, (5) direction, (6) action, (7) rule order, (8) logging, and (9) whether the rule is broader than necessary. Share the rule text and I can walk through each field.';

  // Generic intent-aware answer for arbitrary questions: always respond rather than echoing an error.
  if(/^(what|what is|what are|define|meaning of)/.test(u))
    return`A useful way to understand “${raw.replace(/^what is\s*/i,'')}” is to first identify what problem it solves, where it operates, what data it uses, and what security impact it has. If you give me the exact term or technology, I can break it down with a simple example.`;
  if(/^(why|why is|why are)/.test(u))
    return`The reason usually depends on the security goal. For “${raw}”, identify the asset being protected, the threat being reduced, and the control that changes the risk. If you tell me the exact technology or scenario, I can explain the trade-offs.`;
  if(/^(how|how do|how does|how can)/.test(u))
    return`A safe way to approach “${raw}” is: define the expected result, identify the inputs and trust boundaries, choose the least-privileged control, test it in an authorized environment, and verify the logs/results. Tell me the exact technology and I’ll turn this into concrete steps.`;
  if(/difference|compare|versus|\bvs\b/.test(u))
    return`For “${raw}”, compare the technologies by purpose, layer, state/context, strengths, limitations and typical use cases. If you name the two technologies, I can give you a clear side-by-side comparison.`;

  return`I can work with that question, but I want to avoid inventing a fact. “${raw}” does not match a concept in my offline knowledge set yet. If Gemini is configured with the 🔑 Gemini Key option, I can send the question to Gemini for a full natural-language answer. Without a remote model, I can still help by breaking the question into its security goal, technology, inputs, controls, risks and verification steps.`;
}

async function loadDeviceFirewall(){
  const box=$('deviceFirewallStatus'), title=$('deviceFirewallTitle');
  if(!box)return;
  const online=navigator.onLine;
  const secure=window.isSecureContext===true;
  let storage='Available';
  try{const k='fax-device-check';localStorage.setItem(k,'1');localStorage.removeItem(k);}catch(_){storage='Blocked';}
  const ua=navigator.userAgent||'';
  const platform=navigator.userAgentData?.platform||navigator.platform||'Unknown';
  const browser=/Edg\//i.test(ua)?'Microsoft Edge':/Chrome\//i.test(ua)?'Google Chrome':/Firefox\//i.test(ua)?'Mozilla Firefox':/Safari\//i.test(ua)?'Safari':'Modern browser';
  const networkClass=online?'good':'warn';
  const secureClass=secure?'good':'warn';
  const storageClass=storage==='Available'?'good':'warn';
  if(title)title.textContent=`${browser} — browser environment ready`;
  box.innerHTML=`<div class="deviceStatusHead"><span class="tag">${esc(String(platform))}</span><strong class="good">Browser Check Ready</strong></div><div class="deviceProfiles"><div><b>🌐 Network</b><span class="${networkClass}">${online?'🟢 Online':'🟡 Offline'}</span><span>navigator.onLine: ${online}</span></div><div><b>🔒 Secure Context</b><span class="${secureClass}">${secure?'🟢 Enabled':'🟡 Not detected'}</span><span>Browser security context</span></div><div><b>💾 Storage</b><span class="${storageClass}">${storage==='Available'?'🟢 Available':'🟡 Blocked'}</span><span>Local browser storage</span></div><div><b>🌍 Browser</b><span>${esc(browser)}</span><span>Chrome / Edge compatible</span></div></div><pre class="deviceOutput">Operating system: ${esc(String(platform))}\nBrowser: ${esc(browser)}\nNetwork online: ${online}\nSecure context: ${secure}\nLocal storage: ${storage}\n\nOS firewall status: not queried by the browser.\nUse the platform commands shown below for a real firewall inspection.</pre><small class="muted">Read-only browser check • no OS firewall settings were changed.</small>`;
}
function securityScore(){if(!user)return 0;const lessons=(user.completedLessons||[]).length, courses=(user.completedCourses||[]).length, badges=(user.badges||[]).length, certs=(user.certificates||[]).length, systems=user.firewallCount||0;const totalLessons=allCourses.reduce((n,c)=>n+c.lessons.length,0);return Math.min(100,Math.round((Math.min(user.xp||0,1000)/1000)*35+(Math.min(lessons,totalLessons)/Math.max(totalLessons,1))*25+(Math.min(courses,allCourses.length)/Math.max(allCourses.length,1))*20+(Math.min(badges,8)/8)*10+(Math.min(certs,4)/4)*5+(Math.min(systems,3)/3)*5));}
async function renderProfileDetails(){if(!user){show('login');return;}const score=securityScore();const lvl=Math.floor((user.xp||0)/250)+1;const next=250-((user.xp||0)%250);$('profileDetailGrid').innerHTML=`<div class="card identityCard"><span class="bigIcon">🪪</span><h3>${esc(user.name||'Learner')}</h3><p class="muted">${esc(user.email||'No email')}</p><span class="tag">LEVEL ${lvl}</span><div class="profileMeter"><i style="width:${score}%"></i></div><b>${score}/100 Security Readiness</b></div><div class="card"><span class="bigIcon">📈</span><h3>Learning Analytics</h3><div class="metricRows"><span>⭐ XP <b>${user.xp||0}</b></span><span>🏆 Points <b>${user.points||0}</b></span><span>📚 Lessons <b>${(user.completedLessons||[]).length}</b></span><span>🎓 Courses <b>${(user.completedCourses||[]).length}/${COURSE_DATA.length}</b></span></div><p class="muted">${next} XP until the next level.</p></div><div class="card"><span class="bigIcon">🔥</span><h3>Achievements</h3><div class="metricRows"><span>🔥 Streak <b>${user.streak||0} days</b></span><span>🏅 Badges <b>${(user.badges||[]).length}</b></span><span>📜 Certificates <b>${(user.certificates||[]).length}</b></span><span>🛡️ Firewall Systems <b>${user.firewallCount||0}</b></span></div><button class="secondary full" onclick="show('badges')">View all badges</button></div>`;
$('accountDetails').innerHTML=`<div class="detailGrid"><div><small>FULL NAME</small><b>${esc(user.name||'—')}</b></div><div><small>EMAIL</small><b>${esc(user.email||'—')}</b></div><div><small>USER ID</small><code>${esc(user._id||'local')}</code></div><div><small>ROLE</small><b>${esc(user.role||'learner')}</b></div><div><small>ACCOUNT CREATED</small><b>${user.createdAt?new Date(user.createdAt).toLocaleString():'—'}</b></div><div><small>LAST ACTIVE</small><b>${user.lastActive?new Date(user.lastActive).toLocaleString():'—'}</b></div></div>`;
const r=!user.localOnly?await api('/api/users/'+encodeURIComponent(user._id)+'/activity'):null;const acts=r?.activity||[];if(!acts.length){$('activityTimeline').innerHTML='<div class="empty"><h3>🛰️ No server activity yet</h3><p class="muted">Complete a lesson, quiz, lab or firewall build to create your first activity event.</p></div>';}else{$('activityTimeline').innerHTML=acts.map(x=>`<div class="timelineItem"><span class="timelineDot">${activityIcon(x.event_type)}</span><div><b>${esc(activityLabel(x.event_type))}</b><p>${esc(x.detail||'')}</p><small>${x.created_at?new Date(x.created_at+'Z').toLocaleString():''}</small></div></div>`).join('');}}
function activityIcon(t){return ({registration:'👋',login:'🔐',profile_update:'👤',lesson_completed:'📖',quiz_passed:'🧠',course_completed:'🎓',firewall_saved:'🛡️',resource_opened:'🔎',xp:'⭐'})[t]||'•';}
function activityLabel(t){return ({registration:'Account created',login:'Signed in',profile_update:'Profile updated',lesson_completed:'Lesson completed',quiz_passed:'Quiz passed',course_completed:'Course completed',firewall_saved:'Firewall system saved',resource_opened:'Resource opened',xp:'XP earned'})[t]||'Academy activity';}
const DAILY_MISSIONS=[['Port Detective','Identify TCP 443 and explain why HTTPS is commonly associated with it.','checkPort'],['Rule Architect','Write a narrow HTTPS rule using a trusted source subnet.','showBuilder'],['Threat Hunter','Open Cyber Lab and complete the OWASP mapping challenge.','showLab'],['Policy Auditor','Review ALLOW ANY ANY in the Firewall Builder and explain the risk.','reviewAnyAny']];
function renderDailyMission(){const day=new Date().getDate();const m=DAILY_MISSIONS[day%DAILY_MISSIONS.length];$('dailyMission').innerHTML=`<div class="missionIcon">🎯</div><div><span class="tag">DAILY MISSION</span><h3>${esc(m[0])}</h3><p>${esc(m[1])}</p><button class="primary" onclick="startDailyMission()">Start ${esc(m[0])} →</button></div>`;}
function startDailyMission(){const day=new Date().getDate(),m=DAILY_MISSIONS[day%DAILY_MISSIONS.length];if(m[2]==='checkPort'){show('lab');setTimeout(()=>{const q=$('portQ');if(q)q.value='443';},150)}else if(m[2]==='showBuilder'){show('builder')}else if(m[2]==='showLab'){show('lab');}else{show('builder');setTimeout(()=>{const c=$('fwCode');if(c)c.value='ALLOW ANY ANY';},150)}}
function prepareAdmin(){if($('adminKey'))$('adminKey').value='';$('adminStatus').textContent='Administrator access verified. Load learner records when ready.';}
async function loadAdmin(){if(!sessionStorage.getItem('faxAdminAuth')){const key=$('adminKey').value.trim();const expected=await getAdminPasswordHash();const actual=await hashPassword(key);if(actual!==expected)return $('adminStatus').textContent='Invalid admin password. Please enter the current administrator password.';sessionStorage.setItem('faxAdminAuth','1');}const users=JSON.parse(localStorage.getItem('fwLocalAccounts')||'[]');const learnerData=users.map(x=>({...x,created_at:x.createdAt,updated_at:x.lastActive,completed_lessons:(x.completedLessons||[]).length,completed_courses:(x.completedCourses||[]).length,certificates:(x.certificates||[]).length,firewall_count:x.firewallCount||0}));const total=learnerData.length;const avg=total?Math.round(learnerData.reduce((n,x)=>n+(x.xp||0),0)/total):0;const top=total?Math.max(...learnerData.map(x=>x.xp||0)):0;const certs=learnerData.reduce((n,x)=>n+(x.certificates||[]).length,0);const courses=learnerData.reduce((n,x)=>n+(x.completedCourses||[]).length,0);const systems=learnerData.reduce((n,x)=>n+(x.firewallCount||0),0);$('adminStatus').textContent=`Loaded ${total} browser learner records • Local browser database`;$('adminStats').innerHTML=[['👥','Users',total],['⭐','Average XP',avg],['🏆','Top XP',top],['🎓','Completed Courses',courses],['📜','Certificates',certs],['🛡️','Saved Systems',systems]].map(x=>`<div class="card adminStat"><span>${x[0]}</span><small>${x[1]}</small><b>${x[2]}</b></div>`).join('');$('adminUsers').innerHTML=learnerData.length?learnerData.map(x=>`<article class="card adminUser"><div class="adminUserHead"><div class="avatar">${esc((x.name||'L').slice(0,1).toUpperCase())}</div><div><h3>${esc(x.name)}</h3><p>${esc(x.email||'No email')}</p></div><span class="tag">learner</span></div><div class="adminMetrics"><span>⭐ <b>${x.xp||0}</b> XP</span><span>🏆 <b>${x.points||0}</b> Points</span><span>📖 <b>${x.completed_lessons||0}</b> Lessons</span><span>🎓 <b>${x.completed_courses||0}</b> Courses</span><span>📜 <b>${x.certificates||0}</b> Certificates</span><span>🛡️ <b>${x.firewall_count||0}</b> Systems</span></div><div class="adminDates"><small>Created: ${x.created_at?new Date(x.created_at).toLocaleString():'—'}</small><small>Updated: ${x.updated_at?new Date(x.updated_at).toLocaleString():'—'}</small></div></article>`).join(''):'<div class="card empty"><h3>No browser learners yet</h3></div>'} 


